 raw=zlib.decompress(base64.b85decode(ENCODED[aid][fn]));assert hashlib.sha256(raw).hexdigest()==LOCK[aid]['files'][fn]['sha256'];assert len(raw)==LOCK[aid]['files'][fn]['bytes'];return raw
